"""Execute a parsed ``Query`` against CSV files. See SPEC.md.

Decisions on points the spec leaves open:

- Validation (unknown columns, functions, arity, aggregate placement,
  grouping rules, ORDER BY positions) is done statically before any row is
  evaluated, so it is reported even for empty tables. Type errors (e.g.
  ``'a' + 1``) are only detected when a value is actually computed.
- A NULL operand wins over a type error: ``NULL + 'a'`` is NULL.
- ``AND``/``OR``/``NOT`` and WHERE/HAVING conditions require booleans (or
  NULL); anything else is an error. Both sides of AND/OR are evaluated.
- Booleans are only comparable with booleans (also for ``=``/``IN``);
  numbers with numbers; strings with strings. Anything else is an error.
- ``||`` renders numbers with ``str()`` and booleans as ``true``/``false``.
- ``LIKE``, ``LOWER``, ``UPPER``, ``LENGTH`` require strings; ``ABS`` and
  ``ROUND`` require numbers; ``ROUND``'s second argument must be an int.
- ``ROUND`` uses ``decimal`` on ``repr(x)`` (the shortest decimal that
  round-trips to the float) with ROUND_HALF_UP, i.e. halves away from zero
  as the number is written: ROUND(2.5)=3, ROUND(-2.5)=-3,
  ROUND(2.675, 2)=2.68. Negative ``n`` rounds to tens, hundreds, ...
- Group keys and DISTINCT: NULLs are equal to each other; booleans never
  equal numbers; ``1`` and ``1.0`` are equal (the first row's value is
  what is shown).
- Aggregates are not allowed in GROUP BY.
- DISTINCT is applied before ORDER BY (keeping the first row in file /
  group order); sorting then uses that row's sort keys.
- A table file with duplicate header names (case-insensitively) is fine
  unless the ambiguous name is referenced, which is an error.
"""

import csv
import decimal
import os
import re
from functools import cmp_to_key

from . import QueryError, Result
from .ast import (
    Between,
    Binary,
    Call,
    Column,
    In,
    IsNull,
    Like,
    Literal,
    Unary,
)

AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}
SCALARS = {
    "LOWER": (1, 1),
    "UPPER": (1, 1),
    "LENGTH": (1, 1),
    "ABS": (1, 1),
    "ROUND": (1, 2),
    "COALESCE": (1, None),
}

_INT_RE = re.compile(r"-?[0-9]+")
_FLOAT_RE = re.compile(r"-?[0-9]+\.[0-9]*|-?[0-9]*\.[0-9]+")


# ---------------------------------------------------------------- values


def _is_num(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _type_name(v):
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "boolean"
    if _is_num(v):
        return "number"
    return "string"


def _convert(field):
    if field == "":
        return None
    if _INT_RE.fullmatch(field):
        return int(field)
    if _FLOAT_RE.fullmatch(field):
        return float(field)
    return field


def _value_key(v):
    """Hashable key: bools distinct from numbers, 1 == 1.0."""
    if v is None:
        return ("n",)
    if isinstance(v, bool):
        return ("b", v)
    if _is_num(v):
        return ("x", v)
    return ("s", v)


def _compare(a, b):
    """Compare two non-NULL values; -1, 0 or 1. Raises on mixed types."""
    if _is_num(a) and _is_num(b):
        pass
    elif isinstance(a, bool) and isinstance(b, bool):
        pass
    elif isinstance(a, str) and isinstance(b, str):
        pass
    else:
        raise QueryError(
            "cannot compare %s with %s" % (_type_name(a), _type_name(b))
        )
    if a < b:
        return -1
    if a > b:
        return 1
    return 0


def _text(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    return str(v)


def _require_bool(v, what):
    if v is not None and not isinstance(v, bool):
        raise QueryError("%s requires a boolean, got %s" % (what, _type_name(v)))
    return v


# ---------------------------------------------------------------- tables


def _load_table(directory, name):
    path = os.path.join(str(directory), name + ".csv")
    try:
        with open(path, newline="", encoding="utf-8-sig") as f:
            rows = list(csv.reader(f))
    except FileNotFoundError:
        raise QueryError("unknown table: %s" % name)
    except (OSError, UnicodeDecodeError, csv.Error) as e:
        raise QueryError("cannot read table %s: %s" % (name, e))
    if not rows:
        return [], []
    header = rows[0]
    data = []
    for lineno, raw in enumerate(rows[1:], start=2):
        if not raw:
            continue  # blank line
        if len(raw) != len(header):
            raise QueryError(
                "table %s: row %d has %d fields, expected %d"
                % (name, lineno, len(raw), len(header))
            )
        data.append(tuple(_convert(x) for x in raw))
    return header, data


# ---------------------------------------------------------------- analysis


def _children(e):
    if isinstance(e, (Literal, Column)):
        return []
    if isinstance(e, Unary):
        return [e.operand]
    if isinstance(e, Binary):
        return [e.left, e.right]
    if isinstance(e, IsNull):
        return [e.operand]
    if isinstance(e, In):
        return [e.operand] + list(e.items)
    if isinstance(e, Between):
        return [e.operand, e.low, e.high]
    if isinstance(e, Like):
        return [e.operand, e.pattern]
    if isinstance(e, Call):
        return list(e.args)
    raise QueryError("unsupported expression: %r" % (e,))


def _is_aggregate(e):
    return isinstance(e, Call) and e.name.upper() in AGGREGATES


def _contains_aggregate(e):
    if _is_aggregate(e):
        return True
    return any(_contains_aggregate(c) for c in _children(e))


class _Context:
    def __init__(self, header):
        self.header = header
        self.index = {}
        for i, h in enumerate(header):
            self.index.setdefault(h.lower(), []).append(i)

    def resolve(self, name):
        hits = self.index.get(name.lower())
        if not hits:
            raise QueryError("unknown column: %s" % name)
        if len(hits) > 1:
            raise QueryError("ambiguous column: %s" % name)
        return hits[0]


def _validate(e, ctx, in_aggregate=False):
    """Resolve columns, check functions/arity and aggregate nesting."""
    if isinstance(e, Column):
        ctx.resolve(e.name)
        return
    if isinstance(e, Call):
        name = e.name.upper()
        n = len(e.args)
        if name in AGGREGATES:
            if in_aggregate:
                raise QueryError("aggregate functions cannot be nested")
            if e.star:
                if name != "COUNT":
                    raise QueryError("%s(*) is not allowed" % name)
            elif n != 1:
                raise QueryError("%s takes exactly 1 argument" % name)
            for a in e.args:
                _validate(a, ctx, True)
            return
        if name not in SCALARS:
            raise QueryError("unknown function: %s" % e.name)
        if e.star:
            raise QueryError("%s(*) is not allowed" % name)
        lo, hi = SCALARS[name]
        if n < lo or (hi is not None and n > hi):
            raise QueryError("wrong number of arguments to %s" % name)
    for c in _children(e):
        _validate(c, ctx, in_aggregate)


def _norm(e, ctx):
    """Structural, hashable form of an expression (columns resolved)."""
    if isinstance(e, Column):
        return ("col", ctx.resolve(e.name))
    if isinstance(e, Literal):
        return ("lit", _value_key(e.value))
    if isinstance(e, Unary):
        tag = ("unary", e.op.upper())
    elif isinstance(e, Binary):
        op = e.op.upper()
        tag = ("binary", "!=" if op == "<>" else op)
    elif isinstance(e, IsNull):
        tag = ("isnull", e.negated)
    elif isinstance(e, In):
        tag = ("in", e.negated)
    elif isinstance(e, Between):
        tag = ("between", e.negated)
    elif isinstance(e, Like):
        tag = ("like", e.negated)
    elif isinstance(e, Call):
        tag = ("call", e.name.upper(), e.star)
    else:
        raise QueryError("unsupported expression: %r" % (e,))
    return tag + tuple(_norm(c, ctx) for c in _children(e))


def _check_grouped(e, ctx, group_keys):
    """In a grouped query, columns must be inside aggregates or GROUP BY
    expressions."""
    if _norm(e, ctx) in group_keys:
        return
    if _is_aggregate(e):
        return
    if isinstance(e, Column):
        raise QueryError(
            "column %s must appear in GROUP BY or be used in an aggregate"
            % e.name
        )
    for c in _children(e):
        _check_grouped(c, ctx, group_keys)


# ---------------------------------------------------------------- evaluation


_like_cache = {}


def _like_regex(pattern):
    rx = _like_cache.get(pattern)
    if rx is None:
        parts = []
        for ch in pattern:
            if ch == "%":
                parts.append(".*")
            elif ch == "_":
                parts.append(".")
            else:
                parts.append(re.escape(ch))
        rx = re.compile("".join(parts), re.DOTALL)
        if len(_like_cache) < 1000:
            _like_cache[pattern] = rx
    return rx


def _not(v):
    return None if v is None else (not v)


def _and(a, b):
    if a is False or b is False:
        return False
    if a is None or b is None:
        return None
    return True


def _or(a, b):
    if a is True or b is True:
        return True
    if a is None or b is None:
        return None
    return False


def _round(x, n=None):
    if not _is_num(x):
        raise QueryError("ROUND requires a number, got %s" % _type_name(x))
    if n is not None:
        if not (isinstance(n, int) and not isinstance(n, bool)):
            raise QueryError("ROUND's second argument must be an integer")
    if isinstance(x, float) and (x != x or x in (float("inf"), float("-inf"))):
        if n is None:
            raise QueryError("cannot round %r to an integer" % x)
        return x
    if n is None and isinstance(x, int):
        return x
    d = decimal.Decimal(repr(x)) if isinstance(x, float) else decimal.Decimal(x)
    places = 0 if n is None else max(-400, min(400, n))
    ctx = decimal.Context(prec=2000, rounding=decimal.ROUND_HALF_UP)
    r = d.quantize(decimal.Decimal(1).scaleb(-places), context=ctx)
    if n is None:
        return int(r)
    try:
        return float(r) + 0.0
    except OverflowError:
        raise QueryError("ROUND result out of range")


def _arith(op, a, b):
    if a is None or b is None:
        return None
    if not (_is_num(a) and _is_num(b)):
        raise QueryError(
            "cannot apply %s to %s and %s" % (op, _type_name(a), _type_name(b))
        )
    try:
        if op == "+":
            r = a + b
        elif op == "-":
            r = a - b
        elif op == "*":
            r = a * b
        else:  # "/"
            if b == 0:
                return None
            return float(a / b)
    except OverflowError:
        raise QueryError("numeric overflow in %s" % op)
    if isinstance(a, int) and isinstance(b, int):
        return r
    return float(r)


_COMPARE_OPS = {
    "=": lambda c: c == 0,
    "!=": lambda c: c != 0,
    "<>": lambda c: c != 0,
    "<": lambda c: c < 0,
    "<=": lambda c: c <= 0,
    ">": lambda c: c > 0,
    ">=": lambda c: c >= 0,
}


def _cmp_op(op, a, b):
    if a is None or b is None:
        return None
    return _COMPARE_OPS[op](_compare(a, b))


class _Evaluator:
    def __init__(self, ctx, group_keys=None):
        self.ctx = ctx
        self.group_keys = group_keys or {}

    def eval(self, e, row, group=None):
        """Evaluate ``e`` on ``row``; in a grouped context ``group`` is the
        list of rows of the group and ``row`` its first row (or None)."""
        if isinstance(e, Literal):
            return e.value
        if isinstance(e, Column):
            return row[self.ctx.resolve(e.name)]
        if isinstance(e, Call):
            name = e.name.upper()
            if name in AGGREGATES:
                if group is None:
                    raise QueryError("aggregate %s not allowed here" % name)
                return self._aggregate(e, name, group)
            args = [self.eval(a, row, group) for a in e.args]
            return self._scalar(name, args)
        if isinstance(e, Unary):
            op = e.op.upper()
            v = self.eval(e.operand, row, group)
            if op == "NOT":
                return _not(_require_bool(v, "NOT"))
            if v is None:
                return None
            if not _is_num(v):
                raise QueryError("cannot negate %s" % _type_name(v))
            return -v
        if isinstance(e, Binary):
            op = e.op.upper()
            a = self.eval(e.left, row, group)
            b = self.eval(e.right, row, group)
            if op == "AND":
                return _and(_require_bool(a, "AND"), _require_bool(b, "AND"))
            if op == "OR":
                return _or(_require_bool(a, "OR"), _require_bool(b, "OR"))
            if op in ("+", "-", "*", "/"):
                return _arith(op, a, b)
            if op == "||":
                if a is None or b is None:
                    return None
                return _text(a) + _text(b)
            if op in _COMPARE_OPS:
                return _cmp_op(op, a, b)
            raise QueryError("unknown operator: %s" % e.op)
        if isinstance(e, IsNull):
            v = self.eval(e.operand, row, group)
            return (v is not None) if e.negated else (v is None)
        if isinstance(e, In):
            x = self.eval(e.operand, row, group)
            items = [self.eval(i, row, group) for i in e.items]
            found = False
            saw_null = x is None
            for it in items:
                if it is None:
                    saw_null = True
                elif x is not None and _compare(x, it) == 0:
                    found = True
            r = True if found else (None if saw_null else False)
            return _not(r) if e.negated else r
        if isinstance(e, Between):
            x = self.eval(e.operand, row, group)
            lo = self.eval(e.low, row, group)
            hi = self.eval(e.high, row, group)
            r = _and(_cmp_op("<=", lo, x), _cmp_op("<=", x, hi))
            return _not(r) if e.negated else r
        if isinstance(e, Like):
            s = self.eval(e.operand, row, group)
            p = self.eval(e.pattern, row, group)
            if s is None or p is None:
                return None
            if not (isinstance(s, str) and isinstance(p, str)):
                raise QueryError(
                    "LIKE requires strings, got %s and %s"
                    % (_type_name(s), _type_name(p))
                )
            r = _like_regex(p).fullmatch(s) is not None
            return (not r) if e.negated else r
        raise QueryError("unsupported expression: %r" % (e,))

    def _scalar(self, name, args):
        if name == "COALESCE":
            for a in args:
                if a is not None:
                    return a
            return None
        if any(a is None for a in args):
            return None
        x = args[0]
        if name in ("LOWER", "UPPER", "LENGTH"):
            if not isinstance(x, str):
                raise QueryError("%s requires a string, got %s" % (name, _type_name(x)))
            if name == "LOWER":
                return x.lower()
            if name == "UPPER":
                return x.upper()
            return len(x)
        if name == "ABS":
            if not _is_num(x):
                raise QueryError("ABS requires a number, got %s" % _type_name(x))
            return abs(x)
        if name == "ROUND":
            return _round(*args)
        raise QueryError("unknown function: %s" % name)

    def _aggregate(self, e, name, group):
        if e.star:
            return len(group)
        vals = [self.eval(e.args[0], r, None) for r in group]
        vals = [v for v in vals if v is not None]
        if name == "COUNT":
            return len(vals)
        if not vals:
            return None
        if name in ("SUM", "AVG"):
            for v in vals:
                if not _is_num(v):
                    raise QueryError("%s requires numbers, got %s" % (name, _type_name(v)))
            try:
                total = sum(vals)
                if name == "SUM":
                    return total
                return float(total / len(vals))
            except OverflowError:
                raise QueryError("numeric overflow in %s" % name)
        best = vals[0]
        for v in vals[1:]:
            c = _compare(v, best)
            if (name == "MIN" and c < 0) or (name == "MAX" and c > 0):
                best = v
        return best


# ---------------------------------------------------------------- execute


def _sort_cmp(a, b):
    if a is None:
        return 0 if b is None else -1
    if b is None:
        return 1
    return _compare(a, b)


def execute(query, directory):
    header, rows = _load_table(directory, query.table)
    ctx = _Context(header)

    # Output columns.
    if query.columns is None:
        select_exprs = [Column(h) for h in header]
        names = list(header)
        # Resolve by position (header names may be duplicated).
        star = True
    else:
        star = False
        select_exprs = [item.expr for item in query.columns]
        names = []
        for item in query.columns:
            if item.alias is not None:
                names.append(item.alias)
            elif isinstance(item.expr, Column):
                names.append(header[ctx.resolve(item.expr.name)])
            else:
                names.append(item.text)

    # Static validation.
    if not star:
        for ex in select_exprs:
            _validate(ex, ctx)
    if query.where is not None:
        _validate(query.where, ctx)
        if _contains_aggregate(query.where):
            raise QueryError("aggregate functions are not allowed in WHERE")
    for g in query.group_by:
        _validate(g, ctx)
        if _contains_aggregate(g):
            raise QueryError("aggregate functions are not allowed in GROUP BY")
    if query.having is not None:
        _validate(query.having, ctx)

    # ORDER BY: ("out", index) or ("expr", expr).
    lower_names = [n.lower() for n in names]
    order = []
    for oi in query.order_by:
        ex = oi.expr
        if isinstance(ex, Column) and ex.name.lower() in lower_names:
            order.append(("out", lower_names.index(ex.name.lower()), oi.descending))
        elif (
            isinstance(ex, Literal)
            and isinstance(ex.value, int)
            and not isinstance(ex.value, bool)
        ):
            n = ex.value
            if not 1 <= n <= len(names):
                raise QueryError("ORDER BY position %d is out of range" % n)
            order.append(("out", n - 1, oi.descending))
        else:
            _validate(ex, ctx)
            order.append(("expr", ex, oi.descending))
    order_exprs = [o[1] for o in order if o[0] == "expr"]

    grouped = bool(query.group_by) or any(
        _contains_aggregate(x)
        for x in (
            ([] if star else select_exprs)
            + ([query.having] if query.having is not None else [])
            + order_exprs
        )
    )

    if query.having is not None and not grouped:
        # HAVING without grouping: treat the whole table as one group.
        grouped = True

    if star:
        star_indices = list(range(len(header)))

    if grouped:
        group_keys = {_norm(g, ctx) for g in query.group_by}
        if star:
            for i in star_indices:
                if ("col", i) not in group_keys:
                    raise QueryError(
                        "column %s must appear in GROUP BY or be used in an "
                        "aggregate" % header[i]
                    )
        else:
            for ex in select_exprs:
                _check_grouped(ex, ctx, group_keys)
        if query.having is not None:
            _check_grouped(query.having, ctx, group_keys)
        for ex in order_exprs:
            _check_grouped(ex, ctx, group_keys)

    ev = _Evaluator(ctx)

    # WHERE.
    if query.where is not None:
        kept = []
        for r in rows:
            v = _require_bool(ev.eval(query.where, r), "WHERE")
            if v is True:
                kept.append(r)
        rows = kept

    # Build (row-or-group) units: list of (rep_row, group_rows_or_None).
    if grouped:
        if query.group_by:
            groups = {}
            order_of_groups = []
            for r in rows:
                key = tuple(_value_key(ev.eval(g, r)) for g in query.group_by)
                if key not in groups:
                    groups[key] = []
                    order_of_groups.append(key)
                groups[key].append(r)
            units = [(groups[k][0], groups[k]) for k in order_of_groups]
        else:
            units = [(rows[0] if rows else None, rows)]
        if query.having is not None:
            kept = []
            for rep, grp in units:
                v = _require_bool(ev.eval(query.having, rep, grp), "HAVING")
                if v is True:
                    kept.append((rep, grp))
            units = kept
    else:
        units = [(r, None) for r in rows]

    # Project.
    out = []  # list of (output tuple, sort-expression values)
    for rep, grp in units:
        if star:
            values = tuple(rep[i] for i in star_indices)
        else:
            values = tuple(ev.eval(ex, rep, grp) for ex in select_exprs)
        keys = [ev.eval(ex, rep, grp) for ex in order_exprs]
        out.append((values, keys))

    # DISTINCT.
    if query.distinct:
        seen = set()
        kept = []
        for values, keys in out:
            k = tuple(_value_key(v) for v in values)
            if k not in seen:
                seen.add(k)
                kept.append((values, keys))
        out = kept

    # ORDER BY: successive stable sorts from the last key to the first.
    if order:
        getters = []
        ei = 0
        for kind, ref, desc in order:
            if kind == "out":
                getters.append((lambda item, i=ref: item[0][i], desc))
            else:
                getters.append((lambda item, i=ei: item[1][i], desc))
                ei += 1
        for get, desc in reversed(getters):
            out.sort(
                key=cmp_to_key(lambda a, b, get=get: _sort_cmp(get(a), get(b))),
                reverse=desc,
            )

    result_rows = [values for values, _ in out]

    # LIMIT / OFFSET.
    offset = query.offset or 0
    if offset < 0 or (query.limit is not None and query.limit < 0):
        raise QueryError("LIMIT and OFFSET must not be negative")
    if offset:
        result_rows = result_rows[offset:]
    if query.limit is not None:
        result_rows = result_rows[: query.limit]

    return Result(names, result_rows)

